# ================================================================ part 1
opener(1, 'ערך עתידי של סדרה', 'שאלת החלק: ומה אם מפקידים אותו סכום בכל חודש?',
       ['סדרה: סכום, ריבית ותדירות קבועים', 'ציר זמן: הפקדה ראשונה, אחרונה, ומועד היעד', 'שאלות 4 ו-5: סדרה, וסדרה עם הפקדה ראשונית', 'שאלה 4.1: כשהיעד מאוחר מההפקדה האחרונה'], 15)

S('s-annuity', 'סדרה', 'סדרה: אותו סכום, בכל תקופה',
  '<div class="row eq2 top"><div class="col">'
  + DEF('סדרה (Annuity)', 'תשלומים או הפקדות שחוזרים בתדירות קבועה, באותו סכום ובאותה ריבית. הסכום הקבוע הוא [[pmt|pmt]].', 'אסף משה בע״מ מפקידה 1,000 ש״ח בסוף כל חודש, במשך 4 שנים: 48 הפקדות.', n=1, trm='annuity')
  + ST(2, '<b class="ct">שלוש נקודות על ציר הזמן</b><ol class="lg"><li>' + TX('<b>ההפקדה הראשונה:</b> כאן, בסוף חודש 1.') + '</li><li>' + TX('<b>ההפקדה האחרונה:</b> כאן, בסוף חודש 48.') + '</li><li>' + TX('<b>מועד היעד:</b> לאן רוצים להגיע.') + '</li></ol>', cls='card')
  + '</div><div class="col">' + JAR(3)
  + BAND('dg', 'ה-FV של סדרה מגיע בדיוק למועד ההפקדה האחרונה. כשהיעד מאוחר יותר, צריך עוד שלב.', 4) + '</div></div>'
  + ST(5, TL([0, 1, 2, '...', 48], flows={1: '−1,000', 2: '−1,000', 48: '−1,000'}, marks={0: 'היום'}, W=1100, fs=16), cls='card tlw'), kick='חלק 1 · הגדרה')

_d, _s, _f, _o = fvt([dict(h='החיסכון', rate=0.0025, nper='=4*12', pmt=-1000, pv=0)])
QX('q-4', '', 'שאלה 4: אסף משה בע״מ מפקידה בכל חודש', ['אסף משה בע״מ הפקידה בפיקדון בנקאי, במשך 4 שנים, סכום חודשי קבוע של 1,000 ש״ח. הריבית החודשית 0.25%.', '<b>נדרש:</b> כמה יעמוד לרשות החברה בתום 4 השנים?'],
   'אותה תבנית. הפעם יש pmt, ואין pv.',
   _d, _s, [170, 50, 120], [1], fmt=_f,
   qmc=MEME('חיסכון חודשי', [('tinycoin', '1,000 בחודש. לא מרגישים'), ('giantcoin', 'אחרי 4 שנים: 50,931')], 0, 'sm'),
   hints=['בסדרה rate הוא הריבית לתקופת התשלום: חודש. nper הוא מספר ההפקדות: =4*12.', 'pmt: −1,000 (הפקדה). pv: 0, כי אין סכום חד פעמי היום.'], remind='=FV(C2,C3,C4,C5)', partial=[],
   traps={'C6': [('=FV(C2,C3,C5,C4)', 'ההפקדה החודשית היא pmt, הארגומנט השלישי. pv הוא הרביעי.'), ('=FV(C2,4,C4,C5)', 'nper הוא מספר ההפקדות: 48 חודשים, =4*12.')]},
   steps=[dict(cells={'C6': '=FV(C2,C3,C4,C5)'}, note='=FV(C2,C3,C4,C5): 48 הפקדות של 1,000, ב-0.25% לחודש. יוצא 50,931.21.')],
   note=[('note', 'הפקדנו 48,000. השאר, 2,931.21, הוא ריבית. ההפקדה האחרונה היא בסוף חודש 48, וזה גם מועד היעד, ולכן התוצאה סופית.', 1)],
   done='50,931.21 ש״ח.', xtitle='שאלה 4: אסף משה')

_d, _s, _f, _o = fvt([dict(h='החיסכון', rate=0.004, nper='=3*12', pmt=-2000, pv=-100000)])
QX('q-5', '', 'שאלה 5: זוהר תמם בע״מ, סדרה והפקדה ראשונית', ['זוהר תמם בע״מ הפקידה היום 100,000 ש״ח. בנוסף תפקיד בתום כל חודש, במשך 3 שנים, 2,000 ש״ח. הריבית החודשית 0.4%.', '<b>נדרש:</b> כמה יעמוד לרשות החברה בתום 3 השנים?'],
   'הפעם יש גם pmt וגם pv. שניהם הפקדות, ולכן שניהם שליליים.',
   _d, _s, [170, 50, 120], [1], fmt=_f,
   hints=['nper הוא מספר ההפקדות החודשיות: =3*12.', 'pmt: −2,000. pv: −100,000. פונקציה אחת מחשבת את שניהם יחד.'], remind='=FV(C2,C3,C4,C5)', partial=[],
   traps={'C6': [('=FV(C2,C3,C4)', 'שכחתם את ההפקדה הראשונית: היא pv, הארגומנט הרביעי.')]},
   steps=[dict(cells={'C6': '=FV(C2,C3,C4,C5)'}, note='=FV(C2,C3,C4,C5): גם ה-100,000 וגם 36 ההפקדות צוברים ריבית. יוצא 192,731.46.')],
   note=[('dg', 'סדרה ועוד סכום חד פעמי: פונקציה אחת. pmt לסדרה, pv לסכום של היום.', 1)],
   done='192,731.46 ש״ח.', xtitle='שאלה 5: זוהר תמם')

